import { defineDialect, exact, enumOf } from "kit/define";

// Column types an author may name. There is no date or integer type in the kit,
// so a "date" column is carried as f64 days since 1970-01-01 (UTC) and a whole
// number is an f64.
export const COLUMN_TYPES = ["string", "number", "bool", "date"];
const KIT_TYPE = { string: "str", number: "f64", bool: "bool", date: "f64" };

const DAY_MS = 86400000;

// ---------------------------------------------------------------------------
// Schema walk: plain JavaScript over the record, shared by environment(),
// the slot conventions and the grammar's checks.
//
// Assumed record shape (the draft does not pin it down; see REPORT.md):
//   { name, sources: { sales: { csv, columns } }, params: { … },
//     table: [ { name, from, calls: [ { slot, args } ] } ], chart: [ … ], units }
// The two opening arguments of a table, name("table") and ref("table"), are
// assumed to land as `name` and `from`.
// ---------------------------------------------------------------------------

/** The table's opening arguments, under whichever keys the builder used. */
export function opened(rec) {
  const name = rec.name ?? (Array.isArray(rec.table) ? rec.table[0] : undefined);
  const from = rec.from ?? (Array.isArray(rec.table) ? rec.table[1] : rec.table);
  return { name, from };
}

/**
 * Every table's columns before each of its steps and after the last.
 * Returns { [tableName]: { before: [cols…], after: cols, groupedOver: [cols|null…] } }
 * where cols is { column: authorType }.
 */
export function schemas(program) {
  const out = {};
  for (const [n, s] of Object.entries(program.sources ?? {})) {
    out[n] = { before: [], after: { ...s.columns }, groupedOver: [] };
  }
  for (const rec of program.table ?? []) {
    const { name, from } = opened(rec);
    let cols = { ...(out[from]?.after ?? {}) };
    let grouped = null;      // the columns a run of agg/keepGroups calls aggregates over
    let keys = null;
    let aggCols = null;
    const before = [];
    const groupedOver = [];
    for (const call of rec.calls ?? []) {
      before.push({ ...cols });
      // keepGroups groups the rows as they stand; agg groups what groupBy saw.
      groupedOver.push(call.slot === "keepGroups" ? { ...cols } : grouped ? { ...grouped } : null);
      const a = call.args;
      switch (call.slot) {
        case "rename": {
          const next = {};
          for (const [c, t] of Object.entries(cols)) next[a[0][c] ?? c] = t;
          cols = next;
          break;
        }
        case "cast":
          cols = { ...cols, ...a[0] };
          break;
        case "derive":
          cols = { ...cols, [a[0]]: a[1] };
          break;
        case "groupBy":
          grouped = { ...cols };
          keys = a;
          aggCols = {};
          for (const k of keys) aggCols[k] = cols[k];
          cols = { ...aggCols };
          break;
        case "agg":
          if (aggCols) { aggCols[a[0]] = a[1]; cols = { ...aggCols }; }
          break;
        case "select": {
          const next = {};
          for (const c of a) if (c in cols) next[c] = cols[c];
          cols = next;
          break;
        }
        case "join": {
          const right = out[a[0]]?.after ?? {};
          const on = typeof a[1].on === "string" ? { [a[1].on]: a[1].on } : a[1].on;
          const rightKeys = new Set(Object.values(on));
          const take = a[1].take ?? Object.keys(right).filter((c) => !rightKeys.has(c));
          for (const c of take) cols[c] = right[c];
          break;
        }
        default:
          break;   // filter, semiJoin, sort, limit, trim, replace, dropNulls, dedupe keep columns
      }
      if (call.slot !== "groupBy" && call.slot !== "agg") {
        grouped = null; keys = null; aggCols = null;
      }
    }
    out[name] = { before, after: cols, groupedOver };
  }
  return out;
}

const rowObject = (table, i) => `Row_${table}_${i}`;
const groupObject = (table, i) => `Group_${table}_${i}`;

function rowMembers(cols) {
  const m = {};
  for (const [c, t] of Object.entries(cols)) m[c] = KIT_TYPE[t];
  return m;
}

function groupMembers(cols) {
  const numeric = {};
  const any = {};
  const typed = {};
  for (const [c, t] of Object.entries(cols)) {
    any[c] = { params: [], returns: "f64" };
    typed[c] = { params: [], returns: KIT_TYPE[t] };
    if (t === "number") numeric[c] = { params: [], returns: "f64" };
  }
  const quant = {};
  for (const c of Object.keys(numeric)) quant[c] = { params: ["f64"], returns: "f64" };
  return {
    count: { fn: { params: [], returns: "f64" } },
    sum: { keyed: { what: "numeric column", keys: numeric } },
    mean: { keyed: { what: "numeric column", keys: numeric } },
    sd: { keyed: { what: "numeric column", keys: numeric } },
    quantile: { keyed: { what: "numeric column", keys: quant } },
    min: { keyed: { what: "column", keys: typed } },
    max: { keyed: { what: "column", keys: typed } },
    countDistinct: { keyed: { what: "column", keys: any } },
  };
}

/**
 * Finds the call a lambda sits on. The draft gives ref = { id, kind, on, key },
 * with key "its leading name argument or index"; it does not say index of what.
 * Assumed: the index counts this slot's calls on this table.
 */
function stepOf(ref) {
  const calls = ref.on.calls ?? [];
  let seen = -1;
  for (let i = 0; i < calls.length; i++) {
    if (calls[i].slot !== ref.kind) continue;
    seen++;
    if (typeof ref.key === "number" ? seen === ref.key : calls[i].args[0] === ref.key) return { call: calls[i], index: i };
  }
  return null;
}

const rowSlot = (returns) => (ref, program) => {
  const s = stepOf(ref);
  if (!s) return `no step found for this ${ref.kind} lambda`;
  const table = opened(ref.on).name;
  return { params: [rowObject(table, s.index)], returns: returns(s.call), space: "row" };
};

const groupSlot = (returns) => (ref, program) => {
  const s = stepOf(ref);
  if (!s) return `no step found for this ${ref.kind} lambda`;
  const table = opened(ref.on).name;
  if (!schemas(program)[table]?.groupedOver[s.index]) return `${ref.kind} must follow groupBy(…) (or another ${ref.kind})`;
  return { params: [groupObject(table, s.index)], returns: returns(s.call), space: "group" };
};

function paramType(p) {
  if (p.slider) return { value: "f64", size: true };
  if (p.select) return enumOf(p.select.options);
  if (p.selectNumber) return "f64";
  if (p.selectFrom) return "str";
  if (p.date) return "f64";
  if (p.toggle) return "bool";
  return "f64";
}

const days = (d) => new Date(d * DAY_MS);

export const data = defineDialect({
  name: "data",
  numberType: "f64",
  spaces: {
    row: { pure: true },      // once per row: derive, filter
    group: { pure: true },    // once per group: agg, keepGroups
    scalar: { pure: true },   // once per run: limit
  },
  objects: {
    Params: { label: "the params ($)", members: {} },
  },
  globals: { $: "Params" },
  intrinsics: {
    abs: { params: ["f64"], returns: "f64", ref: Math.abs, spell: { js: "Math.abs($0)" } },
    sqrt: { params: ["f64"], returns: "f64", ref: Math.sqrt, spell: { js: "Math.sqrt($0)" } },
    min: { params: ["f64", "f64"], returns: "f64", ref: Math.min, spell: { js: "Math.min($0, $1)" } },
    max: { params: ["f64", "f64"], returns: "f64", ref: Math.max, spell: { js: "Math.max($0, $1)" } },
    year: {
      params: ["f64"], returns: "f64",
      ref: (d) => days(d).getUTCFullYear(),
      spell: { js: { call: "year($0)", prelude: `const year = (d) => new Date(d * ${DAY_MS}).getUTCFullYear();` } },
    },
    month: {
      params: ["f64"], returns: "f64",
      ref: (d) => days(d).getUTCMonth() + 1,
      spell: { js: { call: "month($0)", prelude: `const month = (d) => new Date(d * ${DAY_MS}).getUTCMonth() + 1;` } },
    },
    truncMonth: {
      params: ["f64"], returns: "f64",
      ref: (d) => { const x = days(d); return Date.UTC(x.getUTCFullYear(), x.getUTCMonth(), 1) / DAY_MS; },
      spell: { js: { call: "truncMonth($0)", prelude: `const truncMonth = (d) => { const x = new Date(d * ${DAY_MS}); return Date.UTC(x.getUTCFullYear(), x.getUTCMonth(), 1) / ${DAY_MS}; };` } },
    },
    monthsBetween: {
      params: ["f64", "f64"], returns: "f64",
      ref: (a, b) => { const x = days(a), y = days(b); return (y.getUTCFullYear() - x.getUTCFullYear()) * 12 + y.getUTCMonth() - x.getUTCMonth(); },
      spell: { js: { call: "monthsBetween($0, $1)", prelude: `const monthsBetween = (a, b) => { const x = new Date(a * ${DAY_MS}), y = new Date(b * ${DAY_MS}); return (y.getUTCFullYear() - x.getUTCFullYear()) * 12 + y.getUTCMonth() - x.getUTCMonth(); };` } },
    },
  },
  library: {
    clamp: { fn: "(x, lo, hi) => min(max(x, lo), hi)" },
  },
  targets: {
    js: { accepts: "*", compare: exact() },
  },
  slots: {
    derive: rowSlot((call) => KIT_TYPE[call.args[1]]),
    filter: rowSlot(() => "bool"),
    agg: groupSlot((call) => KIT_TYPE[call.args[1]]),
    keepGroups: groupSlot(() => "bool"),
    limit: { params: [], returns: "f64", space: "scalar" },
  },

  // Each param becomes a member of $; each table step gets a row object (and,
  // inside a grouping, a group object) with the columns at that point.
  environment(program) {
    const params = {};
    for (const [n, p] of Object.entries(program.params ?? {})) params[n] = paramType(p);
    const objects = { Params: { members: params } };
    const all = schemas(program);
    for (const [table, s] of Object.entries(all)) {
      s.before.forEach((cols, i) => {
        objects[rowObject(table, i)] = { label: `a row of ${table} (row)`, members: rowMembers(cols) };
        const g = s.groupedOver[i];
        if (g) objects[groupObject(table, i)] = { label: `a group of ${table} (g)`, members: groupMembers(g) };
      });
    }
    return { objects };
  },
});

files.data.grammar.js:
import { defineGrammar, name, ref, data, oneOf, rest, enumOf, recordOf } from "kit/define";
import { data as dataDialect, schemas, opened, COLUMN_TYPES } from "./data.dialect.js";

const ColumnType = enumOf(COLUMN_TYPES);

// A source must declare its columns: environment(program) sees only the record,
// never the file, so types cannot be inferred from the data (see REPORT.md).
const SourceShape = { csv: "string", "header?": "boolean", columns: recordOf(ColumnType) };

const ParamShape = oneOf(
  { slider: { value: "number", min: "number", max: "number", "step?": "number", "label?": "string" } },
  { select: { value: "string", options: "string[]", "label?": "string" } },
  { selectNumber: { value: "number", options: "number[]", "label?": "string" } },
  { selectFrom: { value: "string", table: "string", column: "string", "label?": "string" } },
  { date: { value: "string", "label?": "string" } },
  { toggle: { value: "boolean", "label?": "string" } },
);

const JoinShape = { on: oneOf("string", recordOf("string")), "take?": "string[]" };

const EncodingOptions = {
  "type?": enumOf(["quantitative", "time", "ordinal", "nominal"]),
  "format?": "string",
  "sort?": "string",
  "bins?": "number",
  "scheme?": "string",
};

const SQL = /^\s*(select|with)\s/i;

/** Columns of a table before step i (or after its last step). */
function columnsAt(program, table, i) {
  const s = schemas(program)[table];
  if (!s) return null;
  return i === undefined || i >= s.before.length ? s.after : s.before[i];
}

function currentTable(ctx) {
  const tables = ctx.program.table ?? [];
  return tables[tables.length - 1];
}

/** A slot check: every named column exists on the table as it stands. */
function columnsExist(pick) {
  return (call, ctx) => {
    const rec = currentTable(ctx);
    if (!rec) return;
    const { name: table } = opened(rec);
    const cols = columnsAt(ctx.program, table, (rec.calls ?? []).length);
    if (!cols) return;
    pick(call.args).forEach(([col, arg]) => {
      const c = col.startsWith("-") ? col.slice(1) : col;
      if (!(c in cols)) {
        ctx.error("W001", `no column "${c}" on table "${table}"`, { arg, suggest: Object.keys(cols), tip: `columns: ${Object.keys(cols).join(", ")}` });
      }
    });
  };
}

const firstArg = (args) => [[args[0], 0]];
const allArgs = (args) => args.map((c, i) => [c, i]);
const listArg = (args) => (args[0] ?? []).map((c) => [c, 0]);
const keysArg = (args) => Object.keys(args[0] ?? {}).map((c) => [c, 0]);

export const program = defineGrammar(dataDialect, {
  root: "program",
  constructs: {
    program: {
      opens: [name()],
      slots: {
        source: { kind: "decl", args: [name("table"), data(SourceShape)], as: "sources" },
        param: { kind: "decl", args: [name("param"), data(ParamShape)], as: "params" },
        fn: { kind: "unit", unit: "fn" },
        const: { kind: "unit", unit: "const" },
      },
      rejected: {
        sql: { message: "SQL text is not an input language", tip: "build the query with table methods: .table(name, from).join(…).groupBy(…).agg(…).sort(…).limit(…)" },
        view: { message: "views and layout are not part of this language yet: a Program declares data and charts, it does not render them", tip: "declare the table or chart; the host decides how to show it" },
        charts: { message: "a fan-out of charts over the schema needs a build-time lambda, which this language does not have", tip: "declare each chart with .chart(name, table, mark)" },
        component: { message: "new components cannot be declared from a Program", tip: "write the component's expansion out as tables" },
        fragment: { message: "fragments (new methods or attributes on a construct) are not supported", tip: "write the method's expansion out with the core table methods" },
        agent: { message: "agent permissions are not part of a Program in this language", tip: "grant them where the program is opened for editing" },
      },
    },

    table: {
      parent: "program",
      opens: [name("table"), ref("table")],     // .table("sales", "raw")
      record: "calls",
      slots: {
        rename: { kind: "decl", args: [data(recordOf("string"))], check: columnsExist(keysArg) },
        cast: { kind: "decl", args: [data(recordOf(ColumnType))], check: columnsExist(keysArg) },
        trim: { kind: "decl", args: [rest(data("string"))], check: columnsExist(allArgs) },
        replace: { kind: "decl", args: [data("string"), data(recordOf("string"))], check: columnsExist(firstArg) },
        dropNulls: { kind: "decl", args: [data("string[]")], check: columnsExist(listArg) },
        dedupe: { kind: "decl", args: [data("string[]")], check: columnsExist(listArg) },
        select: { kind: "decl", args: [rest(data("string"))], check: columnsExist(allArgs) },
        groupBy: { kind: "decl", args: [rest(data("string"))], check: columnsExist(allArgs) },
        sort: { kind: "decl", args: [rest(data("string"))], check: columnsExist(allArgs) },
        join: { kind: "decl", args: [ref("table"), data(JoinShape)] },
        semiJoin: { kind: "decl", args: [ref("table"), data({ on: oneOf("string", recordOf("string")) })] },
        // The column's type is stated: environment() cannot see a lambda's inferred type.
        derive: { kind: "lambda", slot: "derive", args: [data("string"), data(ColumnType)] },
        filter: { kind: "lambda", slot: "filter" },
        agg: { kind: "lambda", slot: "agg", args: [data("string"), data(ColumnType)] },
        keepGroups: { kind: "lambda", slot: "keepGroups" },
        limit: { kind: "lambda", slot: "limit" },
      },
      check(rec, ctx) {
        const { name: table, from } = opened(rec);
        if (typeof from === "string" && SQL.test(from)) {
          ctx.error("W002", `table "${table}" got a string that reads as SQL. The language does not take SQL text`, {
            arg: 1,
            tip: "build the query with table methods: .table(name, from).join(…).groupBy(…).agg(…).sort(…).limit(…)",
          });
        }
        (rec.calls ?? []).forEach((call, i) => {
          if (call.slot !== "agg") return;
          const prev = rec.calls[i - 1]?.slot;
          if (prev !== "groupBy" && prev !== "agg") ctx.error("W003", `agg "${call.args[0]}" must follow groupBy(…) or another agg`, { tip: "add .groupBy(…) before it" });
        });
      },
    },

    chart: {
      parent: "program",
      opens: [name("chart"), ref("table"), data(enumOf(["line", "bar", "heatmap", "histogram"]))],
      slots: {
        x: { kind: "decl", args: [data("string"), rest(data(EncodingOptions))], once: true },
        // A y bound to a param follows it at run time: { param: "metric" }.
        y: { kind: "decl", args: [data(oneOf("string", { param: "string" })), rest(data(EncodingOptions))], once: true },
        color: { kind: "decl", args: [data("string"), rest(data(EncodingOptions))], once: true },
        tooltip: { kind: "decl", args: [rest(data("string"))], once: true },
        title: { kind: "decl", args: [data("string")], once: true },
      },
      rejected: {
        rule: { message: "reference rules are a fragment in the Dream Code; this language has no fragments", tip: "derive a constant column and layer it as its own chart" },
        layer: { message: "layered charts are not supported", tip: "declare a second chart" },
      },
      check(rec, ctx) {
        const table = rec.table ?? (Array.isArray(rec.chart) ? rec.chart[1] : undefined);
        const cols = columnsAt(ctx.program, table);
        if (!cols) return;
        const named = [];
        for (const k of ["x", "y", "color"]) {
          const v = Array.isArray(rec[k]) ? rec[k][0] : rec[k];
          if (typeof v === "string") named.push([k, v]);
          if (v && typeof v === "object" && "param" in v && !(v.param in (ctx.program.params ?? {}))) {
            ctx.error("W004", `chart encoding ${k} names no param "${v.param}"`, { suggest: Object.keys(ctx.program.params ?? {}) });
          }
        }
        for (const c of [].concat(rec.tooltip ?? [])) named.push(["tooltip", c]);
        for (const [k, c] of named) {
          if (!(c in cols)) ctx.error("W001", `encoding ${k} names "${c}", not a column of "${table}"`, { suggest: Object.keys(cols) });
        }
      },
    },
  },
});

